mapper.select:
SELECT MIN(PI.pi_id) AS piId, PI.inventory_batch_id AS inventoryBatchId, DATE_FORMAT(MIN(PI.pi_date), '%Y-%m-%d') AS piDate, MAX(PI.pi_state) AS piState, W.warehouse_name AS warehouseName, S.section_name AS sectionName, CASE WHEN COUNT(*) = COUNT(CASE WHEN PI.update_state IS NOT NULL THEN 1 END) AND COUNT(DISTINCT PI.update_state) = 1 THEN MAX(PI.update_state) WHEN COUNT(CASE WHEN PI.update_state IS NOT NULL THEN 1 END) > 0 THEN '부분 조정' ELSE '*' END AS adjustmentStatus FROM PhysicalInventory PI JOIN ProductStock PS ON PI.ps_id = PS.ps_id JOIN Section S ON PS.section_id = S.section_id AND PS.warehouse_id = S.warehouse_id JOIN Warehouse W ON S.warehouse_id = W.warehouse_id
AND PS.warehouse_id = #{warehouseId}
AND PS.section_id = #{sectionId}
GROUP BY PI.inventory_batch_id, W.warehouse_name, S.section_name ORDER BY MIN(PI.pi_date) DESC, MIN(PI.pi_id) DESC LIMIT #{size} OFFSET #{skip}

SELECT COUNT(*)
FROM (
    SELECT PI.inventory_batch_id
    FROM PhysicalInventory PI
    JOIN ProductStock PS ON PI.ps_id = PS.ps_id


            AND PS.warehouse_id = #{warehouseId}


            AND PS.section_id = #{sectionId}


    GROUP BY PI.inventory_batch_id
) AS grouped

mapper.update:
UPDATE PhysicalInventory
SET
    pi_state = #{piState}

    , real_quantity = #{realQuantity}
    , different_quantity = #{realQuantity} - pid_quantity
    , update_state = #{updateState}

WHERE
    pi_id = #{piId}

UPDATE PhysicalInventory
SET pi_state = #{piState}
WHERE inventory_batch_id = #{inventoryBatchId}
